```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let done1 = Arc::new(Mutex::new(0i32));
    let done2 = Arc::new(Mutex::new(0i32));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let d1 = Arc::clone(&done1);
    let h1 = thread::spawn(move || {
        {
            let _ga = a1.lock().unwrap();
            let _gb = b1.lock().unwrap();
            *d1.lock().unwrap() = 1;
        }
    });

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let d2 = Arc::clone(&done2);
    let h2 = thread::spawn(move || {
        {
            let _ga = a2.lock().unwrap();
            let _gb = b2.lock().unwrap();
            *d2.lock().unwrap() = 1;
        }
    });

    h1.join().unwrap();
    h2.join().unwrap();

    let v1 = *done1.lock().unwrap();
    let v2 = *done2.lock().unwrap();
    println!("DONE t1={} t2={}", v1, v2);
}
